/**
 * Desafio+ — Axios API Client
 */

import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || '/api',
  timeout: 15000,
  headers: { 'Content-Type': 'application/json' },
});

export default api;

// ── Feed ──────────────────────────────────────────────────
export const feedAPI = {
  getFeed: (params) => api.get('/feed', { params }),
  getExplore: (params) => api.get('/feed/explore', { params }),
};

// ── Posts ─────────────────────────────────────────────────
export const postsAPI = {
  create: (data) => api.post('/posts', data),
  get: (id) => api.get(`/posts/${id}`),
  update: (id, data) => api.put(`/posts/${id}`, data),
  delete: (id) => api.delete(`/posts/${id}`),
  like: (id) => api.post(`/posts/${id}/like`),
  getComments: (id, params) => api.get(`/posts/${id}/comments`, { params }),
  addComment: (id, data) => api.post(`/posts/${id}/comments`, data),
  deleteComment: (postId, commentId) => api.delete(`/posts/${postId}/comments/${commentId}`),
};

// ── Users ─────────────────────────────────────────────────
export const usersAPI = {
  getProfile: (username) => api.get(`/users/${username}`),
  updateProfile: (data) => api.put('/users/me/profile', data),
  getPosts: (username, params) => api.get(`/users/${username}/posts`, { params }),
  follow: (username) => api.post(`/users/${username}/follow`),
  getFollowers: (username, params) => api.get(`/users/${username}/followers`, { params }),
  getFollowing: (username, params) => api.get(`/users/${username}/following`, { params }),
  getSuggestions: () => api.get('/users/suggestions'),
  block: (username) => api.post(`/users/${username}/block`),
  getRanking: (params) => api.get('/users/ranking', { params }),
};

// ── Challenges ────────────────────────────────────────────
export const challengesAPI = {
  getDaily: (params) => api.get('/challenges/daily', { params }),
  getAll: (params) => api.get('/challenges', { params }),
  complete: (data) => api.post('/challenges/complete', data),
  getHistory: (params) => api.get('/challenges/my-history', { params }),
  generateAI: (data) => api.post('/challenges/ai-generate', data),
  getTip: (id) => api.get(`/challenges/${id}/tip`),
};

// ── Games ─────────────────────────────────────────────────
export const gamesAPI = {
  recordSession: (data) => api.post('/games/session', data),
  getLeaderboard: (params) => api.get('/games/leaderboard', { params }),
  getHistory: (params) => api.get('/games/my-history', { params }),
  getStats: () => api.get('/games/my-stats'),
};

// ── Chat ──────────────────────────────────────────────────
export const chatAPI = {
  getConversations: () => api.get('/chat'),
  openWith: (username) => api.get(`/chat/with/${username}`),
  getMessages: (id, params) => api.get(`/chat/${id}/messages`, { params }),
  sendMessage: (id, data) => api.post(`/chat/${id}/messages`, data),
};

// ── Notifications ─────────────────────────────────────────
export const notificationsAPI = {
  getAll: (params) => api.get('/notifications', { params }),
  getUnreadCount: () => api.get('/notifications/unread-count'),
  markAllRead: () => api.post('/notifications/mark-all-read'),
  markRead: (id) => api.patch(`/notifications/${id}/read`),
};

// ── Search ────────────────────────────────────────────────
export const searchAPI = {
  search: (q, type) => api.get('/search', { params: { q, type } }),
};

// ── Upload ────────────────────────────────────────────────
export const uploadAPI = {
  getPresignedUrl: (folder, mimetype) => api.post('/upload/presign', { folder, mimetype }),
  uploadToR2: async (file, folder = 'posts') => {
    const { data } = await uploadAPI.getPresignedUrl(folder, file.type);
    await fetch(data.uploadUrl, {
      method: 'PUT',
      body: file,
      headers: { 'Content-Type': file.type },
    });
    return data.publicUrl;
  },
};

// ── Reports ───────────────────────────────────────────────
export const reportsAPI = {
  report: (data) => api.post('/reports', data),
};
